export const ENEA_OPERATIONAL_REGISTRY: readonly OperationalRegistryRule[] = Object.freeze([
  ...contractRules,
  ...ENEA_USER_AUTHORIZED_RULES,
  ...migratedRules,
  ...ENEA_RUNNER_SYSTEM_RULES,
]);

const ENEA_OPERATIONAL_REGISTRY_BY_ID = new Map(
  ENEA_OPERATIONAL_REGISTRY.map((rule) => [rule.id, rule] as const),
);

export function rulesForStep(step: OperationalProtocolStep) { return ENEA_OPERATIONAL_REGISTRY.filter(rule=>rule.step===step); }
export function registryRule(id: string) { return ENEA_OPERATIONAL_REGISTRY_BY_ID.get(id) ?? null; }
